@page "/chat"
@using sv_f4ac15f8f0dc41258180e8a8bf28c1cd.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "thread-open" : "")">
        <MessageArea ChannelName="@activeChannelName"
                     ChannelDescription="@activeChannelDescription"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadMore="LoadMoreMessages"
                     OnSendMessage="SendMessage" />

        @if (threadOpen)
        {
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    </div>
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<Message> threadReplies = new();
    private Dictionary<int, int> threadReplyCounts = new();
    private Message? threadRootMessage;

    private int activeChannelId;
    private string activeChannelName = string.Empty;
    private string activeChannelDescription = string.Empty;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        var channel = channels.FirstOrDefault(c => c.Id == channelId);
        activeChannelName = channel?.Name ?? string.Empty;
        activeChannelDescription = channel?.Description ?? string.Empty;

        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        threadReplyCounts = await BuildThreadReplyCounts();

        await ChatService.MarkChannelReadAsync(channelId);
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            var newCounts = await BuildThreadReplyCounts();
            foreach (var kv in newCounts)
            {
                threadReplyCounts[kv.Key] = kv.Value;
            }
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count in main view
        if (threadReplyCounts.ContainsKey(threadRootMessage.Id))
            threadReplyCounts[threadRootMessage.Id]++;
        else
            threadReplyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the UI
        var message = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(args.Emoji, new List<string> { "You" }));
            }
        }
    }

    private async Task<Dictionary<int, int>> BuildThreadReplyCounts()
    {
        var counts = new Dictionary<int, int>();
        // Messages with ReplyToId set indicate they're replies; count by root
        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            counts[rootId] = counts.TryGetValue(rootId, out var c) ? c + 1 : 1;
        }
        return await Task.FromResult(counts);
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #2c2f33;
}

.channel-item.active {
    background: #2c2f33;
    border-left-color: #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 12px;
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.thread-open .message-area {
    flex: 0 0 68%;
}

/* Message header */
.message-header-bar {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
}

.channel-title {
    margin: 0;
    font-size: 1.1rem;
}

.channel-desc {
    font-size: 0.8rem;
    color: #666;
}

/* Message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    background: #fafafa;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.8rem;
}

/* Message bubble */
.message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    position: relative;
    transition: background 0.15s;
}

.message-bubble:hover {
    background: #f0f0f0;
}

.message-bubble .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    margin-top: 2px;
    font-size: 0.9rem;
    line-height: 1.4;
}

/* Reactions */
.message-reactions {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #e8f0fe;
    border: 1px solid #d0dff5;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #d0e4fc;
}

/* Thread link */
.thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #4a9eff;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message actions */
.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.action-btn {
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px 8px;
    display: flex;
    gap: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 10;
}

.emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px;
    border-radius: 4px;
    transition: background 0.15s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* Message input */
.message-input {
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.2s;
}

.message-input textarea:focus {
    border-color: #4a9eff;
}

.send-btn {
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.send-btn:hover:not(:disabled) {
    background: #357abd;
}

.send-btn:disabled {
    background: #a0c4f0;
    cursor: not-allowed;
}

/* Thread panel */
.thread-panel {
    width: 32%;
    min-width: 280px;
    border-left: 1px solid #e0e0e0;
    background: #fff;
    display: flex;
    flex-direction: column;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-btn:hover {
    background: #f0f0f0;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f8f9fa;
    border-bottom: 1px solid #e0e0e0;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #444;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #f0f0f0;
}

.thread-reply .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.thread-reply .message-author {
    font-size: 0.85rem;
}

.thread-reply .message-time {
    font-size: 0.7rem;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

