toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #2c2f33;
}

.channel-item.active {
    background: #2c2f33;
    border-left-color: #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 12px;
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.thread-open .message-area {
    flex: 0 0 68%;
}

/* Message header */
.message-header-bar {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
}

.channel-title {
    margin: 0;
    font-size: 1.1rem;
}

.channel-desc {
    font-size: 0.8rem;
    color: #666;
}

/* Message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    background: #fafafa;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.8rem;
}

/* Message bubble */
.message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    position: relative;
    transition: background 0.15s;
}

.message-bubble:hover {
    background: #f0f0f0;
}

.message-bubble .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    margin-top: 2px;
    font-size: 0.9rem;
    line-height: 1.4;
}

/* Reactions */
.message-reactions {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #e8f0fe;
    border: 1px solid #d0dff5;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #d0e4fc;
}

/* Thread link */
.thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #4a9eff;
    cursor: pointer;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message actions */
.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.action-btn {
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px 8px;
    display: flex;
    gap: 6px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 10;
}

.emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px;
    border-radius: 4px;
    transition: background 0.15s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* Message input */
.message-input {
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.2s;
}

.message-input textarea:focus {
    border-color: #4a9eff;
}

.send-btn {
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.send-btn:hover:not(:disabled) {
    background: #357abd;
}

.send-btn:disabled {
    background: #a0c4f0;
    cursor: not-allowed;
}

/* Thread panel */
.thread-panel {
    width: 32%;
    min-width: 280px;
    border-left: 1px solid #e0e0e0;
    background: #fff;
    display: flex;
    flex-direction: column;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-btn:hover {
    background: #f0f0f0;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f8f9fa;
    border-bottom: 1px solid #e0e0e0;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #444;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #f0f0f0;
}

.thread-reply .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.thread-reply .message-author {
    font-size: 0.85rem;
}

.thread-reply .message-time {
    font-size: 0.7rem;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

